// VERSION, FILES and HASHES are generated by tools/build_web.py from the output allowlist.
const PREFIX = `knights-web:${self.registration.scope}:`;
const CACHE = `${PREFIX}${VERSION}`;
const paths = FILES.map((path) => new URL(path, self.registration.scope).href);
self.addEventListener('install', (event) =>
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      let cursor = 0;
      const downloads = await Promise.allSettled(
        Array.from({ length: 6 }, async () => {
          while (cursor < paths.length) {
            const index = cursor++,
              url = paths[index],
              hash = HASHES[FILES[index]],
              cached = await cache.match(url);
            if (cached && (await matchesHash(cached, hash))) continue;
            if (cached) await cache.delete(url);
            const response = await fetch(url, { cache: 'reload' });
            if (!response.ok) throw Error('Offline download failed');
            if (!(await matchesHash(response, hash))) throw Error('Offline file version mismatch');
            await cache.put(url, response);
          }
        }),
      );
      const failed = downloads.find((result) => result.status === 'rejected');
      if (failed) throw failed.reason;
    })(),
  ),
);
async function matchesHash(response, expected) {
  const digest = await crypto.subtle.digest('SHA-256', await response.clone().arrayBuffer());
  return (
    [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, '0')).join('') ===
    expected
  );
}
self.addEventListener('activate', (event) =>
  event.waitUntil(
    (async () => {
      // A second installation under another directory owns its own offline files.
      for (const key of await caches.keys())
        if (key.startsWith(PREFIX) && key !== CACHE) await caches.delete(key);
      await self.clients.claim();
      for (const client of await self.clients.matchAll())
        client.postMessage({ type: 'offline-ready' });
    })(),
  ),
);
self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET' || new URL(event.request.url).origin !== self.location.origin)
    return;
  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE);
      const cached = await cache.match(event.request, { ignoreSearch: true });
      if (cached)
        return event.request.headers.has('Range')
          ? ranged(cached, event.request.headers.get('Range'))
          : cached;
      if (event.request.mode === 'navigate') {
        const page = await cache.match(new URL('index.html', self.registration.scope).href);
        if (page) return page;
      }
      return fetch(event.request);
    })(),
  );
});
async function ranged(response, range) {
  const match = /^bytes=(\d*)-(\d*)$/.exec(range);
  if (!match || (!match[1] && !match[2])) return response;
  const body = await response.blob(),
    length = body.size;
  const start = match[1] ? Number(match[1]) : Math.max(0, length - Number(match[2]));
  const end = match[1] && match[2] ? Math.min(Number(match[2]), length - 1) : length - 1;
  if (start > end || start >= length)
    return new Response(null, { status: 416, headers: { 'Content-Range': `bytes */${length}` } });
  const headers = new Headers(response.headers);
  headers.set('Content-Range', `bytes ${start}-${end}/${length}`);
  headers.set('Content-Length', String(end - start + 1));
  headers.set('Accept-Ranges', 'bytes');
  headers.delete('Content-Encoding');
  return new Response(body.slice(start, end + 1), { status: 206, headers });
}
self.addEventListener('message', (event) => {
  if (event.data?.type === 'activate-update') {
    event.waitUntil(self.skipWaiting());
    return;
  }
  if (event.data?.type !== 'status') return;
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      const keys = await cache.keys();
      if (keys.length === paths.length) event.source?.postMessage({ type: 'offline-ready' });
    })(),
  );
});
